create extension if not exists "pgcrypto";
create table if not exists public.families(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,preferred_language text not null default 'fr' check(preferred_language in('fr','en')),rsvp_completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.family_emails(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,email text not null,created_at timestamptz not null default now(),unique(family_id,email));
create table if not exists public.menu_options(id uuid primary key default gen_random_uuid(),code text not null unique,label_fr text not null,label_en text not null,description_fr text,description_en text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.guests(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,first_name text not null,last_name text,attending boolean,allergies_intolerances text,food_aversions text,menu_option_id uuid references public.menu_options(id) on delete set null,menu_completed_at timestamptz,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_settings(id integer primary key check(id=1),menu_open boolean not null default false,menu_opened_at timestamptz,updated_at timestamptz not null default now());insert into public.site_settings(id,menu_open) values(1,false) on conflict(id) do nothing;
create table if not exists public.photos(id uuid primary key default gen_random_uuid(),guest_name text not null default 'Invité',caption text,storage_path text not null,approved boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.menu_email_log(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,email text not null,provider_id text,success boolean not null default false,error text,sent_at timestamptz not null default now());
alter table public.families enable row level security;alter table public.family_emails enable row level security;alter table public.guests enable row level security;alter table public.menu_options enable row level security;alter table public.site_settings enable row level security;alter table public.photos enable row level security;alter table public.menu_email_log enable row level security;
revoke all on table public.families,public.family_emails,public.guests,public.menu_options,public.site_settings,public.menu_email_log from anon,authenticated;
revoke all on table public.photos from anon,authenticated;grant select,insert on table public.photos to anon,authenticated;
drop policy if exists "public approved photos" on public.photos;create policy "public approved photos" on public.photos for select to anon,authenticated using(approved=true);
drop policy if exists "public insert photos" on public.photos;create policy "public insert photos" on public.photos for insert to anon,authenticated with check(approved=false);
insert into storage.buckets(id,name,public) values('wedding-photos','wedding-photos',true) on conflict(id) do update set public=true;
drop policy if exists "public upload wedding photos" on storage.objects;create policy "public upload wedding photos" on storage.objects for insert to anon,authenticated with check(bucket_id='wedding-photos');
